import os, glob

def check_files(dirpath):
    unique_files = []
    for root, _, files in os.walk(dirpath):
        for f in files:
            p = os.path.join(root, f)
            with open(p, 'r', errors='ignore') as fp:
                content = fp.read()
                # Check for specific non-templated text or check length/structure
                if 'Local variant:' not in content and 'Customer language:' not in content and 'Customer: We use' not in content:
                    unique_files.append((p, content[:150]))
    return unique_files

for d in ['actions', 'evidence', 'operations', 'releases', 'retired', 'support']:
